     private boolean isChecked(final Control control) {
         return control.resolve().isSelected();
     }

     private void check(final Control control, final boolean state) {
         org.openqa.selenium.WebElement element = control.resolve();
         if (element.isSelected() != state) {
             try {
                 element.click();
             } catch (Exception ex) {
                 ((org.openqa.selenium.JavascriptExecutor) driver).executeScript("arguments[0].click();", element);
             }
         }
     }

